    react: {"importLine":"import { Menu } from \"@wizeworks/silicaui-react\";","packageName":"@wizeworks/silicaui-react","props":[],"source":"import { Menu, MenuItem, MenuTitle } from \"@wizeworks/silicaui-react\";\nimport { Section } from \"../lib/Section\";\n\nexport function MenuDemo() {\n    return (\n        <Section title=\"Real use · sidebar navigation\">\n            <Menu className=\"max-w-xs\">\n                <MenuTitle>Workspace</MenuTitle>\n                <MenuItem>\n                    <a href=\"#\" aria-current=\"page\">\n                        Overview\n                    </a>\n                </MenuItem>\n                <MenuItem>\n                    <a href=\"#\">Projects</a>\n                </MenuItem>\n                <MenuItem>\n                    <a href=\"#\">Team</a>\n                </MenuItem>\n                <MenuTitle>Account</MenuTitle>\n                <MenuItem>\n                    <a href=\"#\">Settings</a>\n                </MenuItem>\n                <MenuItem>\n                    <button type=\"button\">Sign out</button>\n                </MenuItem>\n            </Menu>\n        </Section>\n    );\n}"},
