    id: "navbar",
    css: {"classes":["navbar","navbar-center","navbar-end","navbar-start"],"root":"navbar"},
    react: {"importLine":"import { Navbar } from \"@wizeworks/silicaui-react\";","packageName":"@wizeworks/silicaui-react","props":[],"source":"import { Navbar, NavbarStart, NavbarCenter, NavbarEnd, Button } from \"@wizeworks/silicaui-react\";\nimport { Section } from \"../lib/Section\";\n\nexport function NavbarDemo() {\n    return (\n        <>\n            <Section title=\"Real use · site header\">\n                <Navbar className=\"rounded-box border border-base-300\">\n                    <NavbarStart>\n                        <span className=\"text-lg font-bold\">◆ Silica</span>\n                    </NavbarStart>\n                    <NavbarCenter className=\"hidden gap-4 text-sm sm:flex\">\n                        <a href=\"#\">Docs</a>\n                        <a href=\"#\">Components</a>\n                        <a href=\"#\">Pricing</a>\n                    </NavbarCenter>\n                    <NavbarEnd>\n                        <Button variant=\"ghost\" color=\"neutral\">\n                            Sign in\n                        </Button>\n                        <Button color=\"primary\">Get started</Button>\n                    </NavbarEnd>\n                </Navbar>\n            </Section>\n\n            <Section title=\"Glass · floating over a hero\">\n                <div\n                    className=\"flex flex-col gap-24 rounded-box p-4\"\n                    style={{\n                        backgroundImage:\n                            \"linear-gradient(135deg, var(--color-primary), var(--color-accent), var(--color-secondary))\",\n                    }}\n                >\n                    <Navbar className=\"glass\">\n                        <NavbarStart>\n                            <span className=\"text-lg font-bold\">◆ Silica</span>\n                        </NavbarStart>\n                        <NavbarCenter className=\"hidden gap-4 text-sm sm:flex\">\n                            <a href=\"#\">Docs</a>\n                            <a href=\"#\">Components</a>\n                            <a href=\"#\">Pricing</a>\n                        </NavbarCenter>\n                        <NavbarEnd>\n                            <Button variant=\"ghost\" color=\"neutral\">\n                                Sign in\n                            </Button>\n                            <Button color=\"primary\">Get started</Button>\n                        </NavbarEnd>\n                    </Navbar>\n                </div>\n            </Section>\n        </>\n    );\n}"},
    html: {"name":"Navbar","container":true,"behaviors":[],"doc":"Navbar / Table — structural containers (children authored in the tree)."},
