  "app-shell": {
    id: "app-shell",
    css: {"classes":["app-shell","app-shell-footer","app-shell-header","app-shell-main","app-shell-sidebar"],"root":"app-shell"},
    react: {"importLine":"import { AppShell } from \"@wizeworks/silicaui-react\";","packageName":"@wizeworks/silicaui-react","props":[],"source":"import { useState } from \"react\";\nimport {\n    AppShell,\n    AppShellSidebar,\n    AppShellHeader,\n    AppShellMain,\n    AppShellFooter,\n    SidebarProvider,\n    Sidebar,\n    SidebarHeader,\n    SidebarHeaderBrand,\n    SidebarContent,\n    SidebarGroup,\n    SidebarGroupLabel,\n    SidebarItem,\n    SidebarTrigger,\n    Navbar,\n    NavbarStart,\n    NavbarEnd,\n    Footer,\n    Wordmark,\n    Button,\n} from \"@wizeworks/silicaui-react\";\nimport { Section } from \"../lib/Section\";\n\nconst HomeIcon = (\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.75\" strokeLinecap=\"round\" strokeLinejoin=\"round\">\n        <path d=\"M3 12 12 3l9 9\" /> <path d=\"M5 10v10h14V10\" />\n    </svg>\n);\nconst SettingsIcon = (\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.75\" strokeLinecap=\"round\" strokeLinejoin=\"round\">\n        <path d=\"M14 17H5\" /> <path d=\"M19 7h-9\" /> <circle cx=\"17\" cy=\"17\" r=\"3\" /> <circle cx=\"7\" cy=\"7\" r=\"3\" />\n    </svg>\n);\n\nexport function AppShellDemo() {\n    const [active, setActive] = useState(\"dashboard\");\n\n    return (\n        <>\n            <Section title=\"Real use · sidebar + header + footer (same AppShell as below, different slots)\">\n                <div className=\"h-[26rem] w-full max-w-2xl overflow-hidden rounded-box border border-base-300\">\n                    <SidebarProvider>\n                        <AppShell>\n                            <AppShellSidebar>\n                                <Sidebar>\n                                    <SidebarHeader>\n                                        <SidebarHeaderBrand>\n                                            <Wordmark size=\"sm\" color=\"primary\">Acme</Wordmark>\n                                        </SidebarHeaderBrand>\n                                        <SidebarTrigger />\n                                    </SidebarHeader>\n                                    <SidebarContent>\n                                        <SidebarGroup>\n                                            <SidebarGroupLabel>Workspace</SidebarGroupLabel>\n                                            <SidebarItem\n                                                icon={HomeIcon}\n                                                active={active === \"dashboard\"}\n                                                onClick={() => setActive(\"dashboard\")}\n                                            >\n                                                Dashboard\n                                            </SidebarItem>\n                                            <SidebarItem\n                                                icon={SettingsIcon}\n                                                active={active === \"settings\"}\n                                                onClick={() => setActive(\"settings\")}\n                                            >\n                                                Settings\n                                            </SidebarItem>\n                                        </SidebarGroup>\n                                    </SidebarContent>\n                                </Sidebar>\n                            </AppShellSidebar>\n\n                            <AppShellHeader>\n                                <Navbar className=\"border-b border-base-300\">\n                                    <NavbarStart>\n                                        <span className=\"text-sm font-semibold capitalize\">{active}</span>\n                                    </NavbarStart>\n                                    <NavbarEnd>\n                                        <Button size=\"sm\" color=\"primary\">\n                                            New\n                                        </Button>\n                                    </NavbarEnd>\n                                </Navbar>\n                            </AppShellHeader>\n\n                            <AppShellMain className=\"p-6\">\n                                <p className=\"text-sm opacity-70\">\n                                    Content for “{active}” — this pane scrolls independently; try\n                                    collapsing the sidebar.\n                                </p>\n                                {Array.from({ length: 12 }, (_, i) => (\n                                    <p key={i} className=\"mt-3 text-sm opacity-60\">\n                                        Filler paragraph {i + 1} to make the main area scroll.\n                                    </p>\n                                ))}\n                            </AppShellMain>\n\n                            <AppShellFooter>\n                                <Footer center className=\"border-t border-base-300 py-3 text-xs\">\n                                    © 2026 Acme, Inc.\n                                </Footer>\n                            </AppShellFooter>\n                        </AppShell>\n                    </SidebarProvider>\n                </div>\n            </Section>\n\n            <Section title=\"Same AppShell, no sidebar · header + footer only\">\n                <div className=\"h-64 w-full max-w-2xl overflow-hidden rounded-box border border-base-300\">\n                    <AppShell>\n                        <AppShellHeader>\n                            <Navbar className=\"border-b border-base-300\">\n                                <NavbarStart>\n                                    <span className=\"text-sm font-semibold\">Acme</span>\n                                </NavbarStart>\n                            </Navbar>\n                        </AppShellHeader>\n                        <AppShellMain className=\"p-6\">\n                            <p className=\"text-sm opacity-70\">\n                                No sidebar slot rendered — its grid column collapses to zero\n                                automatically.\n                            </p>\n                        </AppShellMain>\n                        <AppShellFooter>\n                            <Footer center className=\"border-t border-base-300 py-3 text-xs\">\n                                © 2026 Acme, Inc.\n                            </Footer>\n                        </AppShellFooter>\n                    </AppShell>\n                </div>\n            </Section>\n        </>\n    );\n}"},
    html: {"name":"AppShell","container":true,"behaviors":[],"doc":"AppShell — lowers to <div>, holding its children."},
  },
