    react: {"importLine":"import { RichTextEditor } from \"@wizeworks/silicaui-editor\";","packageName":"@wizeworks/silicaui-editor","props":[{"iface":"RichTextEditorProps","name":"value","type":"string","required":false,"doc":"Controlled HTML value."},{"iface":"RichTextEditorProps","name":"defaultValue","type":"string","required":false,"doc":"Uncontrolled initial HTML."},{"iface":"RichTextEditorProps","name":"onValueChange","type":"(html: string) => void","required":false,"doc":"Fires with the editor's HTML on every change."},{"iface":"RichTextEditorProps","name":"placeholder","type":"string","required":false,"doc":"Empty-state placeholder text."},{"iface":"RichTextEditorProps","name":"editable","type":"boolean","required":false,"doc":"Allow editing. Default true."},{"iface":"RichTextEditorProps","name":"toolbar","type":"boolean","required":false,"doc":"Show the formatting toolbar. Default true."},{"iface":"RichTextEditorProps","name":"className","type":"string","required":false,"doc":null},{"iface":"RichTextEditorProps","name":"contentClassName","type":"string","required":false,"doc":"Class for the editable content surface."}],"source":"import { useState } from \"react\";\nimport { RichTextEditor } from \"@wizeworks/silicaui-editor\";\nimport { Section } from \"../lib/Section\";\n\nexport function RichTextEditorDemo() {\n    const [doc, setDoc] = useState(\n        \"<h2>Launch checklist</h2><p>Draft the announcement in <strong>rich text</strong> — headings, lists, and links all export as clean HTML.</p><ul><li>Write the copy</li><li>Add screenshots</li></ul>\",\n    );\n\n    return (\n        <Section title=\"Real use · a full formatting toolbar over TipTap\">\n            <RichTextEditor\n                value={doc}\n                onValueChange={setDoc}\n                className=\"max-w-xl\"\n            />\n        </Section>\n    );\n}"},
