    react: {"importLine":"import { ResizablePanels } from \"@wizeworks/silicaui-panels\";","packageName":"@wizeworks/silicaui-panels","props":[],"source":"import {\n    ResizablePanelGroup,\n    ResizablePanel,\n    ResizeHandle,\n} from \"@wizeworks/silicaui-panels\";\nimport { Section } from \"../lib/Section\";\n\nexport function ResizablePanelsDemo() {\n    return (\n        <>\n            <Section title=\"Real use · sidebar + editor + preview\">\n                <ResizablePanelGroup\n                    direction=\"horizontal\"\n                    className=\"h-64 max-w-2xl rounded-box border border-base-300\"\n                >\n                    <ResizablePanel defaultSize={20} minSize={15}>\n                        <div className=\"flex h-full items-center justify-center bg-base-200 text-sm\">\n                            Sidebar\n                        </div>\n                    </ResizablePanel>\n                    <ResizeHandle />\n                    <ResizablePanel defaultSize={50} minSize={30}>\n                        <div className=\"flex h-full items-center justify-center text-sm\">\n                            Editor\n                        </div>\n                    </ResizablePanel>\n                    <ResizeHandle />\n                    <ResizablePanel defaultSize={30} minSize={15}>\n                        <div className=\"flex h-full items-center justify-center bg-base-200 text-sm\">\n                            Preview\n                        </div>\n                    </ResizablePanel>\n                </ResizablePanelGroup>\n            </Section>\n\n            <Section title=\"Vertical stack\">\n                <ResizablePanelGroup\n                    direction=\"vertical\"\n                    className=\"h-64 max-w-md rounded-box border border-base-300\"\n                >\n                    <ResizablePanel defaultSize={50}>\n                        <div className=\"flex h-full items-center justify-center bg-base-200 text-sm\">\n                            Top\n                        </div>\n                    </ResizablePanel>\n                    <ResizeHandle />\n                    <ResizablePanel defaultSize={50}>\n                        <div className=\"flex h-full items-center justify-center text-sm\">\n                            Bottom\n                        </div>\n                    </ResizablePanel>\n                </ResizablePanelGroup>\n            </Section>\n        </>\n    );\n}"},
