    react: {"importLine":"import { Toggle } from \"@wizeworks/silicaui-react\";","packageName":"@wizeworks/silicaui-react","props":[{"iface":"ToggleProps","name":"color","type":"SilicaColor","required":false,"doc":"Accent color; maps to toggle-<color> (checked track fill)."},{"iface":"ToggleProps","name":"size","type":"SilicaSize","required":false,"doc":"Default md."},{"iface":"ToggleProps","name":"children","type":"React.ReactNode","required":false,"doc":"Caption. Wraps the control in a <label> so the text is a click target."}],"source":"import { useState } from \"react\";\nimport { Toggle } from \"@wizeworks/silicaui-react\";\nimport { Section } from \"../lib/Section\";\nimport { ColorVariantSizeGrid } from \"../lib/ColorGrid\";\n\nexport function ToggleDemo() {\n    const [wifi, setWifi] = useState(true);\n\n    return (\n        <>\n            <ColorVariantSizeGrid\n                Component={Toggle}\n                render={({ color, size }) => (\n                    <label className=\"flex items-center gap-2 text-sm\">\n                        <Toggle color={color} size={size} defaultChecked />\n                        {color ?? size}\n                    </label>\n                )}\n            />\n\n            <Section title=\"Real use · Wi-Fi setting\">\n                <label className=\"flex items-center gap-2 text-sm\">\n                    <Toggle\n                        color=\"primary\"\n                        checked={wifi}\n                        onChange={(e) => setWifi(e.target.checked)}\n                    />\n                    Wi-Fi is {wifi ? \"on\" : \"off\"}\n                </label>\n            </Section>\n        </>\n    );\n}"},
